typedef struct edge { int to; int w; struct edge *next; } edge_t;
typedef struct { int n; bool directed; edge_t *adj[MAXV]; } graph_t;

static void add_directed_edge(graph_t *g, int u, int v, int w) {
    edge_t *e = malloc(sizeof *e);
    if (!e) return;
    e->to = v; e->w = w; e->next = NULL;
    edge_t **pp = &g->adj[u];        // 이중 포인터로 꼬리 슬롯 추적
    while (*pp) pp = &(*pp)->next;
    *pp = e;                         // 삽입 순서 보존(append)
}
void graph_add_edge(graph_t *g, int u, int v, int w) {
    if (u < 0 || u >= g->n || v < 0 || v >= g->n) return;
    add_directed_edge(g, u, v, w);
    if (!g->directed) add_directed_edge(g, v, u, w);
}

int bfs(const graph_t *g, int src, int *out) {
    bool visited[MAXV] = {false};
    int q[MAXV], qh = 0, qt = 0, cnt = 0;
    visited[src] = true; q[qt++] = src;      // 넣을 때 표시
    while (qh < qt) {
        int u = q[qh++];
        out[cnt++] = u;
        for (edge_t *e = g->adj[u]; e; e = e->next)
            if (!visited[e->to]) { visited[e->to] = true; q[qt++] = e->to; }
    }
    return cnt;
}

// 재귀
static void dfs_visit(const graph_t *g, int u, bool *vis, int *out, int *cnt) {
    vis[u] = true; out[(*cnt)++] = u;
    for (edge_t *e = g->adj[u]; e; e = e->next)
        if (!vis[e->to]) dfs_visit(g, e->to, vis, out, cnt);
}
int dfs_recursive(const graph_t *g, int src, int *out) {
    bool vis[MAXV] = {false}; int cnt = 0;
    dfs_visit(g, src, vis, out, &cnt);
    return cnt;
}
// 반복 (명시적 스택, 이웃 역순 push -> 재귀와 동일 순서)
int dfs_iterative(const graph_t *g, int src, int *out) {
    bool vis[MAXV] = {false}; int st[MAXV], sp = 0, cnt = 0;
    vis[src] = true; st[sp++] = src;
    while (sp > 0) {
        int u = st[--sp]; out[cnt++] = u;
        int nbr[MAXV], m = 0;
        for (edge_t *e = g->adj[u]; e; e = e->next) nbr[m++] = e->to;
        for (int i = m - 1; i >= 0; --i)
            if (!vis[nbr[i]]) { vis[nbr[i]] = true; st[sp++] = nbr[i]; }
    }
    return cnt;
}

int connected_components(const graph_t *g) {
    bool visited[MAXV] = {false}; int comps = 0, q[MAXV];
    for (int s = 0; s < g->n; ++s) {
        if (visited[s]) continue;
        ++comps;                              // 새 요소
        int qh = 0, qt = 0; visited[s] = true; q[qt++] = s;
        while (qh < qt) {
            int u = q[qh++];
            for (edge_t *e = g->adj[u]; e; e = e->next)
                if (!visited[e->to]) { visited[e->to] = true; q[qt++] = e->to; }
        }
    }
    return comps;
}

int num_islands(int rows, int cols, int *grid) {
    if (rows <= 0 || cols <= 0) return 0;
    int islands = 0, cap = rows * cols;
    int *q = malloc(sizeof(int) * (size_t)cap);
    if (!q) return -1;
    const int dr[4] = {-1,1,0,0}, dc[4] = {0,0,-1,1};
    for (int r = 0; r < rows; ++r) for (int c = 0; c < cols; ++c) {
        if (grid[r*cols+c] != 1) continue;
        ++islands;
        int qh = 0, qt = 0; grid[r*cols+c] = 0; q[qt++] = r*cols+c;
        while (qh < qt) {
            int cell = q[qh++], cr = cell/cols, cc = cell%cols;
            for (int d = 0; d < 4; ++d) {
                int nr = cr+dr[d], nc = cc+dc[d];
                if (nr<0||nr>=rows||nc<0||nc>=cols) continue;
                if (grid[nr*cols+nc] == 1) { grid[nr*cols+nc] = 0; q[qt++] = nr*cols+nc; }
            }
        }
    }
    free(q);
    return islands;
}

int topological_sort(const graph_t *g, int *out) {
    int indeg[MAXV] = {0};
    for (int u = 0; u < g->n; ++u)
        for (edge_t *e = g->adj[u]; e; e = e->next) indeg[e->to]++;
    int q[MAXV], qh = 0, qt = 0;
    for (int v = 0; v < g->n; ++v) if (indeg[v] == 0) q[qt++] = v;
    int cnt = 0;
    while (qh < qt) {
        int u = q[qh++]; out[cnt++] = u;
        for (edge_t *e = g->adj[u]; e; e = e->next)
            if (--indeg[e->to] == 0) q[qt++] = e->to;
    }
    return (cnt == g->n) ? cnt : -1;          // -1 = 사이클
}

problems.signature:
void dsu_init(dsu_t *d, int n);
int dsu_find(dsu_t *d, int x);
bool dsu_union(dsu_t *d, int a, int b);

problems.solution:
typedef struct { int parent[MAXV]; int rank_[MAXV]; int count; } dsu_t;
void dsu_init(dsu_t *d, int n) {
    for (int i = 0; i < n; ++i) { d->parent[i] = i; d->rank_[i] = 0; }
    d->count = n;
}
int dsu_find(dsu_t *d, int x) {
    while (d->parent[x] != x) {
        d->parent[x] = d->parent[d->parent[x]];   // 경로 압축
        x = d->parent[x];
    }
    return x;
}
bool dsu_union(dsu_t *d, int a, int b) {
    int ra = dsu_find(d, a), rb = dsu_find(d, b);
    if (ra == rb) return false;                    // 이미 같은 집합
    if (d->rank_[ra] < d->rank_[rb]) { int t = ra; ra = rb; rb = t; }
    d->parent[rb] = ra;
    if (d->rank_[ra] == d->rank_[rb]) d->rank_[ra]++;
    d->count--;
    return true;
}

void dijkstra(const graph_t *g, int src, int *dist) {
    bool done[MAXV] = {false};
    for (int i = 0; i < g->n; ++i) dist[i] = INF;
    dist[src] = 0;
    for (int it = 0; it < g->n; ++it) {
        int u = -1, best = INF;
        for (int v = 0; v < g->n; ++v)
            if (!done[v] && dist[v] < best) { best = dist[v]; u = v; }
        if (u == -1) break;                        // 남은 게 도달 불가
        done[u] = true;
        for (edge_t *e = g->adj[u]; e; e = e->next)
            if (!done[e->to] && dist[u] + e->w < dist[e->to])
                dist[e->to] = dist[u] + e->w;       // relax
    }
}

enum { WHITE = 0, GRAY = 1, BLACK = 2 };
static bool dfs_cycle(const graph_t *g, int u, int *color) {
    color[u] = GRAY;
    for (edge_t *e = g->adj[u]; e; e = e->next) {
        if (color[e->to] == GRAY) return true;     // back edge -> 사이클
        if (color[e->to] == WHITE && dfs_cycle(g, e->to, color)) return true;
    }
    color[u] = BLACK;
    return false;
}
bool detect_cycle_directed(const graph_t *g) {
    int color[MAXV] = {WHITE};
    for (int s = 0; s < g->n; ++s)
        if (color[s] == WHITE && dfs_cycle(g, s, color)) return true;
    return false;
}
